# Hintergrund: (id, Abschnitt, Stelle, Kontext, Konfidenz, Thema, Text, unsicher, Belege, Quellen, Fachwörter | Mundart)
BACKGROUND = [
 ("BG-MAT-3001", U(15, 1, 20), "MAT.15.2", READERS, "probable", "Die Überlieferung der Ältesten",
  "Mit der «Überlieferung der Ältesten» (παράδοσις τῶν πρεσβυτέρων) sind Auslegungen und Bräuche gemeint, die Lehrer neben der geschriebenen Tora weitergaben. Josephus berichtet, die Pharisäer hätten dem Volk Vorschriften aus der Überlieferung der Väter weitergegeben, die nicht im Gesetz des Mose aufgeschrieben seien; die Sadduzäer liessen nur das Geschriebene gelten. Die Mischna (um 200 n. Chr.) beginnt ihren Traktat Avot mit einer Kette von Überlieferern von Mose bis zu den Männern der «Grossen Versammlung» und mit deren Rat, «einen Zaun um die Tora» zu machen; die Kette wird danach bis zu Hillel und Schammai weitergeführt. Das Händewaschen vor dem Essen gehörte zu solchen Bräuchen (zu den Einzelheiten BG-MRK-1010).",
  "Wie weit Laien zur Zeit Jesu Reinheitsbräuche wie das Händewaschen übten, ist umstritten; die Mischna ist über ein Jahrhundert später aufgeschrieben und spiegelt nicht einfach die Lage um 30 n. Chr.",
  ["MAT.15.1-MAT.15.9", "MRK.7.3-MRK.7.5"], ["Josephus, Jüdische Altertümer 13,297", "Mischna, Avot 1,1–12"],
  [("grc", "παράδοσις", "Überlieferung"), ("grc", "πρεσβύτερος", "Ältester; Lehrer früherer Generationen")],
  "D Überliferig vo de Ältischte",
  "Mit de «Überliferig vo de Ältischte» (παράδοσις τῶν πρεσβυτέρων) sind Uslegige und Brüüch gmeint, wo Lehrer näbe de gschribne Tora wiitergää händ. De Josephus brichtet, d Pharisäer hebed em Volk Vorschrifte us de Überliferig vo de Vätter wiitergää, wo nöd im Gsetz vom Mose ufgschribe seged; d Sadduzäer händ nu s Gschribne la gälte. D Mischna (um 200 n. Chr.) fangt iren Traktat Avot mit ere Chette vo Überliferer aa, vom Mose bis zu de Manne vo de «Grosse Versammlig», und mit irem Rat, «en Haag um d Tora» z mache; nachher gaat d Chette wiiter bis zum Hillel und zum Schammai. S Händwäsche vor em Ässe hät zu settige Brüüch ghört (zu de Einzelheite BG-MRK-1010).",
  "Wie wiit Laie zur Ziit vo Jesus Reinheitsbrüüch wie s Händwäsche gmacht händ, isch umstritte; d Mischna isch meh als es Jaarhundert spööter ufgschribe worde und spieglet nöd eifach d Laag um 30 n. Chr.",
  ["Überliferig", "Ältischte; Lehrer vo früenere Generatione"]),
 ("BG-MAT-3002", U(15, 21, 28), "MAT.15.22", READERS, "probable", "Kanaanäer, Tyros und Sidon",
  "«Kanaanäer» ist der alte biblische Name für die Bewohner des Landes vor Israel; nach [[GEN.10.15]] ist Sidon der Erstgeborene Kanaans, und das Gebiet der Kanaanäer reicht von Sidon an ([[GEN.10.19]]). Zur Zeit Jesu gehörten die Hafenstädte Tyros und Sidon zur römischen Provinz Syrien; sie waren griechisch geprägt und mit Galiläa wirtschaftlich verbunden (vgl. [[MAT.11.21-MAT.11.22]]). Indem Matthäus die Frau «kanaanäisch» nennt, wo Markus die zeitgenössische Bezeichnung «Syrophönizierin» gebraucht ([[MRK.7.26]]), erinnert er an die alte Gegnerschaft zwischen Israel und den Völkern des Landes. Hunde galten in jüdischen Texten meist als unrein und verächtlich; «Hund» konnte ein Schimpfwort sein ([[1SA.17.43]]). Das Wort in [[MAT.15.26-MAT.15.27]] (κυνάριον) ist eine Verkleinerungsform und lässt an Hunde im Haus denken. Zu Tyros und Sidon siehe auch BG-MRK-1011.",
  "Ob die Verkleinerungsform das Bild mildert, ist umstritten; im Griechischen der Zeit verloren solche Formen oft ihre verkleinernde Bedeutung.",
  ["MAT.15.21-MAT.15.28", "GEN.10.15-GEN.10.19", "MAT.11.21-MAT.11.22", "MRK.7.26", "1SA.17.43"], [],
  [("grc", "Χαναναῖος", "kanaanäisch, Kanaanäer"), ("grc", "κυνάριον", "Hündchen"), ("heb", "כְּנַעַן", "Kanaan", "kᵉnaʿan")],
  "Kanaanäer, Tyros und Sidon",
  "«Kanaanäer» isch de alt biblisch Name für d Bewoner vom Land vor Israel; nach [[GEN.10.15]] isch Sidon de Erschtgeboren vo Kanaan, und s Gebiet vo de Kanaanäer fangt bi Sidon aa ([[GEN.10.19]]). Zur Ziit vo Jesus händ d Hafestedt Tyros und Sidon zur römische Provinz Syrie ghört; si sind griechisch prägt gsii und mit Galiläa wirtschaftlich verbunde (vgl. [[MAT.11.21-MAT.11.22]]). Wil de Matthäus d Frau «kanaanäisch» nännt, wo de Markus d Bezeichnig vo sinere Ziit «Syrophönizierin» bruucht ([[MRK.7.26]]), erinneret er a di alt Gägnerschaft zwüsche Israel und de Völker vom Land. Hünd händ i jüdische Texte meischt als unrein und verächtlich gulte; «Hund» hät es Schimpfwort chöne sii ([[1SA.17.43]]). S Wort i [[MAT.15.26-MAT.15.27]] (κυνάριον) isch e Verchliinerigsform und laat a Hünd im Huus dänke. Zu Tyros und Sidon lueg au BG-MRK-1011.",
  "Öb d Verchliinerigsform s Bild milderet, isch umstritte; im Griechische vo dere Ziit händ settigi Forme oft iri verchliinernd Bedüütig verlore.",
  ["kanaanäisch, Kanaanäer", "Hündli", "Kanaan"]),
 ("BG-MAT-3003", U(15, 32, 39), "MAT.15.39", GAL, "possible", "Magadan",
  "Nach der zweiten Speisung fährt Jesus in das Gebiet von Magadan ([[MAT.15.39]]). Ein Ort dieses Namens ist sonst nicht bekannt; [[MRK.8.10]] nennt an der entsprechenden Stelle Dalmanuta, das ebenfalls nicht sicher zu verorten ist. Andere Handschriften lesen «Magdala»; Magdala war ein bedeutender Ort am Westufer des Sees, griechisch wohl Tarichea genannt (BG-MRK-1002), und Heimat der Maria aus Magdala ([[MAT.27.56]]). Ob Magadan eine andere Form desselben Namens ist, lässt sich nicht entscheiden.",
  "Die Gleichsetzung von Magdala mit Tarichea ist verbreitet, aber nicht unbestritten. Magadan und Dalmanuta bleiben unbekannt.",
  ["MAT.15.39", "MRK.8.10", "MAT.27.56"], [],
  [("grc", "Μαγαδάν", "Magadan (Ortsname)")],
  "Magadan",
  "Nach de zweite Spiisig faart de Jesus is Gebiet vo Magadan ([[MAT.15.39]]). En Ort mit dem Name isch süscht nöd bekannt; [[MRK.8.10]] nännt a de entspräched Stell Dalmanuta, wo me au nöd sicher cha verorte. Anderi Handschrifte läsed «Magdala»; Magdala isch en wichtige Ort am Weschtufer vom See gsii, griechisch wohl Tarichea gnännt (BG-MRK-1002), und d Heimet vo de Maria us Magdala ([[MAT.27.56]]). Öb Magadan e anderi Form vom gliiche Name isch, cha me nöd entscheide.",
  "D Gliichsetzig vo Magdala mit Tarichea isch verbreitet, aber nöd unbestritte. Magadan und Dalmanuta bliibed unbekannt.",
  ["Magadan (Ortsname)"]),
 ("BG-MAT-3004", U(16, 1, 4), "MAT.16.1", TEMPLE, "probable", "Die Sadduzäer",
  "Die Sadduzäer waren eine Gruppe vor allem aus der priesterlichen und wohlhabenden Oberschicht Jerusalems. Nach Josephus anerkannten sie nur die geschriebenen Gebote und nicht die Überlieferung der Väter, verneinten ein Fortleben der Seele sowie Lohn und Strafe nach dem Tod; nach [[ACT.23.8]] lehnten sie die Auferstehung ab (vgl. [[MAT.22.23]]). Mit den Pharisäern standen sie oft im Streit. Dass Matthäus beide Gruppen mehrfach zusammen nennt ([[MAT.3.7]]; [[MAT.16.1-MAT.16.12]]), entspricht keiner geschichtlichen Partei, sondern fasst die führenden Gruppen als gemeinsame Gegner Jesu zusammen. Nach der Zerstörung des Tempels (70 n. Chr.) verschwinden die Sadduzäer aus den Quellen.",
  "Fast alles, was über die Sadduzäer bekannt ist, stammt von Aussenstehenden oder Gegnern (Josephus, Neues Testament, rabbinische Texte). Wie weit Hohepriester und Sadduzäer gleichzusetzen sind, ist umstritten.",
  ["MAT.16.1-MAT.16.12", "MAT.3.7", "MAT.22.23", "ACT.23.8"],
  ["Josephus, Jüdischer Krieg 2,164–166", "Josephus, Jüdische Altertümer 13,297–298; 18,16–17"],
  [("grc", "Σαδδουκαῖος", "Sadduzäer"), ("heb", "צְדוּקִים", "Sadduzäer (rabbinische Bezeichnung)", "ṣᵉdûqîm")],
  "D Sadduzäer",
  "D Sadduzäer sind e Gruppe vor allem us de prieschterliche und riiche Oberschicht vo Jerusalem gsii. Nach em Josephus händ si nu di gschribne Gebot aaerchännt und nöd d Überliferig vo de Vätter, händ verneint, dass d Seel wiiterläbt und dass es nach em Tod Loon und Straf git; nach [[ACT.23.8]] händ si d Uferstehig abglehnt (vgl. [[MAT.22.23]]). Mit de Pharisäer sind si oft im Striit gsii. Dass de Matthäus beid Gruppe meermal zäme nännt ([[MAT.3.7]]; [[MAT.16.1-MAT.16.12]]), entspricht kei gschichtliche Partei, sondern fasst di füerende Gruppe als gmeinsami Gägner vo Jesus zäme. Nach de Zerstörig vom Tämpel (70 n. Chr.) verschwinded d Sadduzäer us de Quälle.",
  "Fascht alles, was me über d Sadduzäer weiss, stammt vo Ussestehende oder Gägner (Josephus, Nöis Teschtament, rabbinischi Texte). Wie wiit me Hoheprieschter und Sadduzäer cha gliichsetze, isch umstritte.",
  ["Sadduzäer", "Sadduzäer (rabbinischi Bezeichnig)"]),
 ("BG-MAT-3005", U(16, 13, 20), "MAT.16.17-MAT.16.18", READERS, "probable", "Simon Barjona, Kephas, Petrus",
  "«Barjona» ist aramäisch und heisst «Sohn des Jona» ([[MAT.16.17]]); nach [[JHN.1.42]] heisst der Vater des Simon Johannes. Den Beinamen, den Jesus Simon gibt, überliefert das Neue Testament griechisch als Πέτρος und in aramäischer Form als Kephas (Κηφᾶς, [[JHN.1.42]]; [[1CO.1.12]]; [[GAL.2.9]]); beides geht auf das aramäische kêpāʾ «Stein, Fels» zurück. Als Personenname ist das Wort vor dem Christentum kaum belegt. Im Aramäischen fällt das Wortspiel von [[MAT.16.18]] in einem einzigen Wort zusammen («du bist Kepha, und auf diesen Kepha …»); im Griechischen unterscheiden sich der Name (männlich) und «Fels» (πέτρα, weiblich).",
  "Ob Jesus das Wort aramäisch gesprochen hat und in welcher Form, ist nicht überliefert; die aramäische Fassung ist eine Rekonstruktion. Ob «Jona» eine Kurzform von Johannes ist, ist offen. Für einen älteren aramäischen Beleg des Namens wird ein Papyrus aus Elephantine angeführt; seine Lesung ist umstritten, und die Angabe ist hier nicht am Text nachgeprüft.",
  ["MAT.16.17-MAT.16.18", "JHN.1.42", "1CO.1.12", "GAL.2.9"], [],
  [("arc", "בַּר יוֹנָה", "Sohn des Jona", "bar yônâ"), ("arc", "כֵּיפָא", "Stein, Fels", "kêpāʾ"), ("grc", "Κηφᾶς", "Kephas (griechische Umschrift)"), ("grc", "Πέτρος", "Petrus")],
  "Simon Barjona, Kephas, Petrus",
  "«Barjona» isch aramäisch und heisst «Sohn vom Jona» ([[MAT.16.17]]); nach [[JHN.1.42]] heisst de Vatter vom Simon Johannes. De Biiname, wo de Jesus em Simon git, überliferet s Nöi Teschtament griechisch als Πέτρος und i aramäischer Form als Kephas (Κηφᾶς, [[JHN.1.42]]; [[1CO.1.12]]; [[GAL.2.9]]); beides gaat uf s aramäisch kêpāʾ «Stei, Felse» zrugg. Als Personename isch s Wort vor em Christetum chuum belegt. Im Aramäische fallt s Wortspiel vo [[MAT.16.18]] i eim einzige Wort zäme («du bisch Kepha, und uf dä Kepha …»); im Griechische underscheided sich de Name (männlich) und «Felse» (πέτρα, wiiblich).",
  "Öb de Jesus s Wort aramäisch gseit hät und i wellere Form, isch nöd überliferet; di aramäisch Fassig isch e Rekonstruktion. Öb «Jona» e Churzform vo Johannes isch, isch offe. Für en eltere aramäische Beleg vom Name wird en Papyrus us Elephantine aagfüert; wie me en liist, isch umstritte, und d Aagaab isch da nöd am Text nachprüeft.",
  ["Sohn vom Jona", "Stei, Felse", "Kephas (griechischi Umschrift)", "Petrus"]),
 ("BG-MAT-3006", U(16, 13, 20), "MAT.16.18", READERS, "probable", "Die Tore des Totenreichs",
  "ᾅδης (Hades) ist in der griechischen Bibel das Totenreich, hebräisch šᵉʾôl, der Ort aller Toten, nicht der Strafort; dafür steht bei Matthäus γέεννα («Hölle», BG-MAT-3009). Das Bild von Toren des Totenreichs bzw. des Todes ist biblisch: Hiskija klagt, er müsse «zu den Toren des Totenreichs» gehen ([[ISA.38.10]]); ein Beter bittet, Gott möge ihn «von den Toren des Todes» heraufholen ([[PSA.9.13]]; vgl. [[PSA.107.18]]; [[WIS.16.13]]). Die Tore stehen für die Macht des Todes, der niemand entkommt. [[MAT.16.18]] sagt der Gemeinde zu, dass diese Macht sie nicht überwältigen wird.",
  "Ob die Tore angreifen oder sich gegen einen Ansturm halten, ist umstritten (siehe Übersetzungsentscheidung zu [[MAT.16.18]]).",
  ["MAT.16.18", "ISA.38.10", "PSA.9.13", "PSA.107.18", "WIS.16.13"], [],
  [("grc", "ᾅδης", "Hades, Totenreich"), ("heb", "שְׁאוֹל", "Totenreich, Scheol", "šᵉʾôl"), ("grc", "γέεννα", "Gehenna, Hölle (Ort des Gerichts)")],
  "D Tor vom Totereich",
  "ᾅδης (Hades) isch i de griechische Bible s Totereich, hebräisch šᵉʾôl, de Ort vo allne Tote, nöd de Straafort; für dä staat bim Matthäus γέεννα («Höll», BG-MAT-3009). S Bild vo Tor vom Totereich bzw. vom Tod isch biblisch: De Hiskija chlagt, er müess «zu de Tor vom Totereich» gaa ([[ISA.38.10]]); en Bätter bittet, Gott söll en «vo de Tor vom Tod» ufehole ([[PSA.9.13]]; vgl. [[PSA.107.18]]; [[WIS.16.13]]). D Tor stönd für d Macht vom Tod, wo niemer devo chunnt. [[MAT.16.18]] seit de Gmeind zue, dass die Macht si nöd wird überwältige.",
  "Öb d Tor aagriiffed oder sich gäge en Aasturm halted, isch umstritte (lueg d Übersetzigsentscheidig zu [[MAT.16.18]]).",
  ["Hades, Totereich", "Totereich, Scheol", "Gehenna, Höll (Ort vom Gricht)"]),
 ("BG-MAT-3007", U(16, 13, 20), "MAT.16.19", READERS, "probable", "Schlüssel, binden und lösen",
  "Schlüssel waren Zeichen der Vollmacht eines Hausverwalters: Nach [[ISA.22.22]] legt Gott Eljakim «den Schlüssel des Hauses David» auf die Schulter; was er öffnet, schliesst niemand, und was er schliesst, öffnet niemand. In der späteren rabbinischen Sprache heissen «binden» und «lösen» (hebräisch ʾāsar und hittîr, aramäisch auch šᵉrāʾ) «verbieten» und «erlauben», gelegentlich auch «mit dem Bann belegen» und «vom Bann lösen». Josephus sagt von den Pharisäern unter Königin Salome Alexandra, sie hätten nach Belieben verbannen und zurückrufen, lösen und binden können; dort ist politische Macht gemeint. Zu den Deutungen siehe INT-MAT-3004.",
  "Die rabbinischen Belege sind später als Matthäus; ob die Begriffe im 1. Jahrhundert schon diese feste Bedeutung hatten, ist nicht sicher.",
  ["MAT.16.19", "MAT.18.18", "ISA.22.22", "MAT.23.13"], ["Josephus, Jüdischer Krieg 1,111"],
  [("grc", "κλείς", "Schlüssel"), ("heb", "אָסַר", "binden; verbieten", "ʾāsar"), ("heb", "הִתִּיר", "lösen; erlauben", "hittîr"), ("arc", "שְׁרָא", "lösen; erlauben", "šᵉrāʾ")],
  "Schlüssel, binde und löse",
  "Schlüssel sind Zeiche vo de Vollmacht vo me Huusverwalter gsii: Nach [[ISA.22.22]] leit Gott em Eljakim «de Schlüssel vom Huus David» uf d Schultere; was er uftuet, macht niemer zue, und was er zuetuet, macht niemer uf. I de spöötere rabbinische Spraach heissed «binde» und «löse» (hebräisch ʾāsar und hittîr, aramäisch au šᵉrāʾ) «verbiete» und «erlaube», mängisch au «mit em Bann belegge» und «vom Bann löse». De Josephus seit vo de Pharisäer under de Königin Salome Alexandra, si hebed nach Beliebe chöne verbanne und zruggrüefe, löse und binde; dört isch politischi Macht gmeint. Zu de Düütige lueg INT-MAT-3004.",
  "D rabbinische Beleg sind spööter als de Matthäus; öb d Begriff im 1. Jaarhundert scho die fescht Bedüütig gha händ, isch nöd sicher.",
  ["Schlüssel", "binde; verbiete", "löse; erlaube", "löse; erlaube"]),
 ("BG-MAT-3008", U(16, 21, 28), "MAT.16.24", READERS, "probable", "Das Kreuz auf sich nehmen",
  "Bei der römischen Kreuzigung musste der Verurteilte oft den Querbalken selbst zur Hinrichtungsstätte tragen (vgl. [[JHN.19.17]]; bei Matthäus wird Simon von Kyrene dazu gezwungen, [[MAT.27.32]]). Plutarch nennt es als bekanntes Bild, dass jeder Verbrecher, der zur Hinrichtung geführt wird, sein Kreuz trägt. «Sein Kreuz auf sich nehmen» ([[MAT.16.24]]; schon [[MAT.10.38]]) war für die ersten Hörer also ein Bild für den Weg in eine schändliche Hinrichtung, die Rom vor allem Aufständischen und Sklaven vorbehielt (zur Kreuzigung BG-MRK-2010).",
  "Ob Jesus das Wort vor seiner eigenen Kreuzigung so gesagt hat oder ob es in der Überlieferung von ihr her geprägt ist, ist umstritten.",
  ["MAT.16.24-MAT.16.25", "MAT.10.38", "MAT.27.32", "JHN.19.17"],
  ["Plutarch, Über die späte Strafe der Gottheit (Moralia 554 A–B)"],
  [("grc", "σταυρός", "Kreuz; Pfahl")],
  "S Chrüüz uf sich nää",
  "Bi de römische Chrüzigung hät de Verurteilt oft de Querbalke sälber zur Hiirichtigsstett müese träge (vgl. [[JHN.19.17]]; bim Matthäus wird de Simon vo Kyrene dezue zwunge, [[MAT.27.32]]). De Plutarch nännt s als bekannts Bild, dass jede Verbrächer, wo zur Hiirichtig gfüert wird, sis Chrüüz treit. «Sis Chrüüz uf sich nää» ([[MAT.16.24]]; scho [[MAT.10.38]]) isch für di erschte Zuelooser also es Bild gsii für de Wäg i e schandbari Hiirichtig, wo Rom vor allem für Ufständischi und Sklave vorgsee hät (zur Chrüzigung BG-MRK-2010).",
  "Öb de Jesus s Wort vor sinere eigete Chrüzigung eso gseit hät oder öb s i de Überliferig vo ire här prägt isch, isch umstritte.",
  ["Chrüüz; Pfaal"]),
 ("BG-MAT-3009", U(18, 6, 9), "MAT.18.6-MAT.18.9", READERS, "probable", "Mühlstein und Gehenna",
  "Der «grosse Mühlstein» (μύλος ὀνικός, wörtlich «Esels-Mühlstein») ist der schwere Läuferstein einer Mühle, die von einem Esel gedreht wurde, im Unterschied zur Handmühle im Haushalt ([[MAT.24.41]]). Mit einem solchen Stein im Meer versenkt zu werden, war ein Bild für einen Tod ohne Rückkehr und ohne Begräbnis. «Hölle» (γέεννα) geht auf das Tal Hinnom (gê hinnōm) südlich von Jerusalem zurück, wo nach [[JER.7.31-JER.7.32]] Kinder verbrannt worden waren und das der Prophet zum «Tal des Mordens» erklärt. In jüdischen Texten der Zeit wurde der Name zum Bild für den Ort des Gerichts. Matthäus spricht von der «Hölle des Feuers» ([[MAT.18.9]]; vgl. [[MAT.5.22]]).",
  "Dass im Hinnomtal zur Zeit Jesu ständig Abfall verbrannt worden sei, wird oft behauptet, ist aber erst in mittelalterlichen Quellen bezeugt.",
  ["MAT.18.6-MAT.18.9", "MAT.24.41", "JER.7.31-JER.7.32", "MAT.5.22"], [],
  [("grc", "μύλος ὀνικός", "Esels-Mühlstein, grosser Mühlstein"), ("grc", "γέεννα", "Gehenna, Hölle"), ("heb", "גֵּי הִנֹּם", "Tal Hinnom", "gê hinnōm")],
  "Mülistei und Gehenna",
  "De «grossi Mülistei» (μύλος ὀνικός, wörtlich «Esels-Mülistei») isch de schwär Lauferstei vo ere Müli, wo vo me Esel tribe worde isch, im Underschiid zur Handmüli im Hushalt ([[MAT.24.41]]). Mit eme settige Stei im Meer versänkt z wärde, isch es Bild gsii für en Tod ohni Zrugg und ohni Grab. «Höll» (γέεννα) gaat ufs Tal Hinnom (gê hinnōm) südlich vo Jerusalem zrugg, wo nach [[JER.7.31-JER.7.32]] Chind verbrännt worde sind und wo de Prophet zum «Tal vom Morde» erklärt. I jüdische Texte vo dere Ziit isch de Name zum Bild für de Ort vom Gricht worde. De Matthäus redt vo de «Höll vom Füür» ([[MAT.18.9]]; vgl. [[MAT.5.22]]).",
  "Dass im Hinnomtal zur Ziit vo Jesus immer Abfall verbrännt worde seg, wird oft bhauptet, isch aber erscht i mittelalterliche Quälle bezüügt.",
  ["Esels-Mülistei, grosse Mülistei", "Gehenna, Höll", "Tal Hinnom"]),
 ("BG-MAT-3010", U(17, 1, 8), "MAT.17.1", GAL, "possible", "Der Berg der Verwandlung",
  "Matthäus nennt den Berg nicht, nur «einen hohen Berg» ([[MAT.17.1]]). Ein Psalmenkommentar, der Origenes (3. Jahrhundert) zugeschrieben wird, nennt den Tabor in Galiläa; seit dem 4. Jahrhundert ist diese Ortsangabe verbreitet; wegen der Nähe zu Cäsarea Philippi ([[MAT.16.13]]) denken andere an den Hermon. Für Matthäus sind Berge Orte der Offenbarung: die Versuchung ([[MAT.4.8]]), die Bergpredigt ([[MAT.5.1]]), die Heilungen ([[MAT.15.29]]), die Sendung durch den Auferstandenen ([[MAT.28.16]]). Mose und Elija begegneten Gott beide auf dem Berg Sinai bzw. Horeb ([[EXO.24.15-EXO.24.18]]; [[1KI.19.8-1KI.19.13]]). Der Vorschlag des Petrus, drei Hütten (σκηναί) zu machen ([[MAT.17.4]]), erinnert manche an das Laubhüttenfest ([[LEV.23.42-LEV.23.43]]).",
  "Die Ortsüberlieferung ist spät; welcher Berg gemeint ist, lässt sich nicht bestimmen. Ob der Vorschlag mit den Hütten auf das Laubhüttenfest anspielt, ist unsicher.",
  ["MAT.17.1-MAT.17.8", "EXO.24.15-EXO.24.18", "1KI.19.8-1KI.19.13", "LEV.23.42-LEV.23.43"],
  ["Origenes (zugeschrieben), Kommentar zu Psalm 88(89),13"],
  [("grc", "σκηνή", "Zelt, Hütte")],
  "De Bärg vo de Verwandlig",
  "De Matthäus nännt de Bärg nöd, nu «en hööche Bärg» ([[MAT.17.1]]). En Psalmekommentar, wo me em Origenes (3. Jaarhundert) zueschriibt, nännt de Tabor in Galiläa; sit em 4. Jaarhundert isch die Ortsaagaab verbreitet; wäge de Nööchi zu Cäsarea Philippi ([[MAT.16.13]]) dänked anderi a de Hermon. Für de Matthäus sind Bärge Ort vo de Offebarig: d Versuechig ([[MAT.4.8]]), d Bärgpredig ([[MAT.5.1]]), d Heilige ([[MAT.15.29]]), d Sändig dur de Uferstandnig ([[MAT.28.16]]). De Mose und de Elija sind Gott beidi uf em Bärg Sinai bzw. Horeb begägnet ([[EXO.24.15-EXO.24.18]]; [[1KI.19.8-1KI.19.13]]). De Vorschlag vom Petrus, drüü Hütte (σκηναί) z mache ([[MAT.17.4]]), erinneret mängi as Laubhüttefescht ([[LEV.23.42-LEV.23.43]]).",
  "D Ortsüberliferig isch spoot; weli Bärg gmeint isch, cha me nöd bestimme. Öb de Vorschlag mit de Hütte ufs Laubhüttefescht aaspilt, isch unsicher.",
  ["Zält, Hütte"]),
 ("BG-MAT-3011", U(17, 9, 13), "MAT.17.10", READERS, "probable", "Die Erwartung des wiederkommenden Elija",
  "Nach [[MAL.4.5-MAL.4.6]] sendet Gott den Propheten Elija, bevor der Tag des Herrn kommt; er soll das Herz der Väter den Söhnen zuwenden. Jesus Sirach nimmt das auf: Elija sei bereit, den Zorn zu stillen und die Stämme Jakobs wiederherzustellen ([[SIR.48.10]]). Weil Elija nach [[2KI.2.11]] lebend in den Himmel aufgenommen wurde, erwartete man seine Rückkehr. Die Mischna lässt Elija kommen, um Streitfragen zu klären und Frieden zu stiften; der Christ Justin lässt seinen jüdischen Gesprächspartner Tryphon sagen, der Messias bleibe unbekannt, bis Elija ihn salbe. Die Frage der Jünger ([[MAT.17.10]]) setzt solche Erwartungen voraus.",
  "Mischna und Justin stammen aus dem 2. Jahrhundert; ob die Lehre «Elija kommt vor dem Messias» schon zur Zeit Jesu fest war, ist umstritten.",
  ["MAT.17.10-MAT.17.13", "MAL.4.5-MAL.4.6", "SIR.48.10", "2KI.2.11", "MAT.11.14"],
  ["Mischna, Edujot 8,7", "Justin, Dialog mit Tryphon 8,4; 49,1"],
  [("grc", "ἀποκαθίστημι", "wiederherstellen")],
  "D Erwartig, dass de Elija wider chunnt",
  "Nach [[MAL.4.5-MAL.4.6]] schickt Gott de Prophet Elija, bevor de Tag vom Herr chunnt; er söll s Härz vo de Vätter de Söön zuewände. De Jesus Sirach nimmt das uf: De Elija seg parat, de Zorn z stille und d Stämm vo Jakob wider härzstelle ([[SIR.48.10]]). Wil de Elija nach [[2KI.2.11]] läbig in Himel ufgnoo worde isch, hät me erwartet, dass er zruggchunnt. D Mischna laat de Elija choo, zum Striitfrage kläre und Fride stifte; de Christ Justin laat sin jüdische Gsprächspartner Tryphon säge, de Messias bliibi unbekannt, bis de Elija en salbi. D Frag vo de Jünger ([[MAT.17.10]]) setzt settigi Erwartige voruus.",
  "D Mischna und de Justin stammed us em 2. Jaarhundert; öb d Lehr «De Elija chunnt vor em Messias» scho zur Ziit vo Jesus fescht gsii isch, isch umstritte.",
  ["wider härstelle"]),
 ("BG-MAT-3012", U(17, 14, 21), "MAT.17.15", READERS, "probable", "Mondsucht und «heilige Krankheit»",
  "σεληνιάζομαι kommt von σελήνη «Mond»: In der Antike glaubte man verbreitet, der Mond löse Anfälle aus. Die geschilderten Zeichen – Fallen ins Feuer und ins Wasser ([[MAT.17.15]]) – erinnern viele an Epilepsie, die die Griechen auch «heilige Krankheit» nannten, weil man göttliche oder dämonische Ursachen vermutete. Eine Schrift aus der Schule des Hippokrates («Über die heilige Krankheit», 5./4. Jahrhundert v. Chr.) bestreitet das bereits und führt die Krankheit auf natürliche Ursachen zurück. Matthäus nennt die Mondsüchtigen neben den Besessenen ([[MAT.4.24]]) und spricht in [[MAT.17.18]] von einem Dämon; Krankheit und dämonische Macht werden in den Evangelien nicht immer getrennt.",
  "Eine heutige Diagnose lässt sich aus der Schilderung nicht sicher stellen; die Gleichsetzung mit Epilepsie ist eine Vermutung.",
  ["MAT.17.14-MAT.17.18", "MAT.4.24"], ["Hippokratisches Corpus, Über die heilige Krankheit"],
  [("grc", "σεληνιάζομαι", "mondsüchtig sein, Anfälle haben"), ("grc", "σελήνη", "Mond")],
  "Mondsucht und «heiligi Chrankheit»",
  "σεληνιάζομαι chunnt vo σελήνη «Mond»: I de Antike hät me verbreitet glaubt, de Mond löös Aafäll uus. D Zeiche, wo bschribe wärded – is Füür und is Wasser gheie ([[MAT.17.15]]) –, erinnered vili a Epilepsie, wo d Grieche au «heiligi Chrankheit» gnännt händ, wil me göttlichi oder dämonischi Ursache vermuetet hät. E Schrift us de Schuel vom Hippokrates («Über die heilige Krankheit», 5./4. Jaarhundert v. Chr.) bestriitet das scho und füert d Chrankheit uf natürlichi Ursache zrugg. De Matthäus nännt d Mondsüchtige näbe de Bsässne ([[MAT.4.24]]) und redt i [[MAT.17.18]] vo me Dämon; Chrankheit und dämonischi Macht wärded i de Evangelie nöd immer trännt.",
  "E hütigi Diagnose cha me us de Bschriibig nöd sicher stelle; d Gliichsetzig mit Epilepsie isch e Vermuetig.",
  ["mondsüchtig sii, Aafäll haa", "Mond"]),
 ("BG-MAT-3013", U(17, 24, 27), "MAT.17.24", TEMPLE, "probable", "Doppeldrachme und Tempelsteuer",
  "Nach [[EXO.30.11-EXO.30.16]] gab jeder gemusterte Israelit einen halben Schekel für das Heiligtum; [[NEH.10.32]] spricht von einem Drittel Schekel jährlich. Zur Zeit Jesu zahlten jüdische Männer jährlich einen halben Schekel an den Tempel in Jerusalem, auch in der Diaspora; Josephus erzählt von Städten in Mesopotamien, wo die Doppeldrachmen gesammelt und nach Jerusalem gebracht wurden. Die Mischna widmet der Abgabe den Traktat Schekalim; danach standen im Monat Adar Wechseltische im Land. Die Doppeldrachme entsprach dem halben Schekel, ein Stater (Vierdrachmenstück, oft die Silbermünze von Tyros) zwei solchen Abgaben ([[MAT.17.27]]). Nach der Zerstörung des Tempels liess Kaiser Vespasian die Abgabe als Steuer für den Tempel des Jupiter Capitolinus in Rom weiter einziehen.",
  "Ob die Abgabe zur Zeit Jesu schon allgemein jährlich gezahlt wurde, ist umstritten; eine Schrift aus Qumran (4Q159) verlangt den halben Schekel nur einmal im Leben. Ob Matthäus an die Tempel- oder an die römische Abgabe denkt, hängt auch an der Datierung des Evangeliums (INT-MAT-3005).",
  ["MAT.17.24-MAT.17.27", "EXO.30.11-EXO.30.16", "NEH.10.32"],
  ["Josephus, Jüdische Altertümer 18,312", "Josephus, Jüdischer Krieg 7,218", "Mischna, Schekalim 1,3", "Qumran, 4Q159"],
  [("grc", "δίδραχμον", "Doppeldrachme"), ("grc", "στατήρ", "Stater (Vierdrachmenstück)"), ("heb", "שֶׁקֶל", "Schekel", "šeqel")],
  "Doppeldrachme und Tämpelstüür",
  "Nach [[EXO.30.11-EXO.30.16]] hät jede gmuschteret Israelit en halbe Schekel für s Heiligtum ggää; [[NEH.10.32]] redt vo me Drittel Schekel im Jaar. Zur Ziit vo Jesus händ jüdischi Manne jedes Jaar en halbe Schekel a de Tämpel z Jerusalem zalt, au i de Diaspora; de Josephus verzellt vo Stedt in Mesopotamie, wo d Doppeldrachme gsammlet und uf Jerusalem brocht worde sind. D Mischna widmet de Abgaab de Traktat Schekalim; dernaa sind im Monet Adar Wächseltisch im Land gstande. D Doppeldrachme hät em halbe Schekel entsproche, en Stater (Vierdrachmestuck, oft d Silbermünz vo Tyros) zwei settige Abgaabe ([[MAT.17.27]]). Nach de Zerstörig vom Tämpel hät de Kaiser Vespasian d Abgaab als Stüür für de Tämpel vom Jupiter Capitolinus z Rom wiiter la iiziee.",
  "Öb d Abgaab zur Ziit vo Jesus scho allgemein jedes Jaar zalt worde isch, isch umstritte; e Schrift us Qumran (4Q159) verlangt de halb Schekel nu eimal im Läbe. Öb de Matthäus a d Tämpel- oder a d römischi Abgaab dänkt, hangt au a de Datierig vom Evangelium (INT-MAT-3005).",
  ["Doppeldrachme", "Stater (Vierdrachmestuck)", "Schekel"]),
 ("BG-MAT-3014", U(18, 10, 14), "MAT.18.10", READERS, "probable", "Engel vor dem Angesicht Gottes",
  "Dass Menschen Engel haben, die für sie eintreten oder sie schützen, ist im Judentum der Zeit bezeugt: Gott befiehlt seinen Engeln, den Gerechten zu behüten ([[PSA.91.11]]); im Buch Tobit begleitet der Engel Rafael den Tobias und sagt von sich, er sei einer der sieben Engel, die vor der Herrlichkeit des Herrn stehen ([[TOB.12.15]]). In [[ACT.12.15]] meinen die Versammelten, an der Tür stehe «sein Engel». Das «Angesicht sehen» stammt aus der Sprache des Hofes: Nur die nächsten Diener stehen ständig vor dem König (vgl. [[2KI.25.19]]). [[MAT.18.10]] sagt damit: Gerade die Kleinen haben bei Gott die nächsten Fürsprecher.",
  "Eine ausgearbeitete Lehre von persönlichen Schutzengeln ist später; der Text sagt nur, dass «ihre Engel» Gottes Angesicht sehen.",
  ["MAT.18.10", "PSA.91.11", "TOB.12.15", "ACT.12.15", "2KI.25.19"], [],
  [("grc", "ἄγγελος", "Bote, Engel")],
  "Ängel vor em Aagsicht vo Gott",
  "Dass Mänsche Ängel händ, wo für si iiträtted oder si schützed, isch im Judetum vo dere Ziit bezüügt: Gott befiilt sine Ängel, de Grächte z bhüete ([[PSA.91.11]]); im Buech Tobit begleitet de Ängel Rafael de Tobias und seit vo sich, er sig eine vo de sibe Ängel, wo vor de Herrlichkeit vom Herr stönd ([[TOB.12.15]]). I [[ACT.12.15]] meined di Versammlete, a de Tür stöi «sin Ängel». S «Aagsicht gsee» stammt us de Spraach vom Hof: Nu di nööchschte Diener stönd immer vor em König (vgl. [[2KI.25.19]]). [[MAT.18.10]] seit demit: Grad d Chliine händ bi Gott di nööchschte Fürspräch.",
  "E uusgarbeiteti Lehr vo persönliche Schutzängel isch spööter; de Text seit nu, dass «iri Ängel» s Aagsicht vo Gott gsehnd.",
  ["Bot, Ängel"]),
 ("BG-MAT-3015", U(18, 21, 35), "MAT.18.21", READERS, "possible", "Wie oft vergeben?",
  "Die Frage des Petrus setzt eine Diskussion über das Mass der Vergebung voraus. Der Babylonische Talmud überliefert die Lehre, Gott vergebe einem Menschen dieselbe Übertretung bis zum dritten Mal, beim vierten nicht mehr (mit Verweis auf [[AMO.2.6]] und [[JOB.33.29]]); an der folgenden Stelle heisst es, wer einen anderen gekränkt hat, solle ihn höchstens dreimal um Vergebung bitten. Gemessen daran ist das «siebenmal» des Petrus grosszügig; Jesu Antwort hebt das Zählen ganz auf. Die Zahl erinnert an das Lied Lamechs, der sich «siebenundsiebzigmal» rächen will ([[GEN.4.24]]): Der masslosen Rache wird die masslose Vergebung gegenübergestellt.",
  "Der Talmud ist Jahrhunderte jünger als Matthäus; ob solche Regeln schon zur Zeit Jesu galten, ist nicht bekannt. Der Anklang an [[GEN.4.24]] beruht auf dem gleichen griechischen Zahlwort (FIND-MAT-3014).",
  ["MAT.18.21-MAT.18.22", "GEN.4.24", "LUK.17.4"], ["Babylonischer Talmud, Joma 86b–87a"],
  [],
  "Wie mängisch vergää?",
  "D Frag vom Petrus setzt e Diskussion über s Mass vom Vergää voruus. De Babylonisch Talmud überliferet d Lehr, Gott vergäbi eme Mänsch di gliich Übertrettig bis zum dritte Mal, bim vierte nüme (mit Verwiis uf [[AMO.2.6]] und [[JOB.33.29]]); a de Stell dernaa heissts, wär en andere kränkt hät, söll en höchschtens drüü Mal um Vergäbig bitte. Dra gmässe isch s «sibe Mal» vom Petrus grosszügig; d Antwort vo Jesus hebt s Zelle ganz uf. D Zaal erinneret as Lied vom Lamech, wo sich «sibenesibezg Mal» rääche wott ([[GEN.4.24]]): De masslose Rach wird s masslose Vergää gägenübergstellt.",
  "De Talmud isch Jaarhunderti jünger als de Matthäus; öb settigi Regle scho zur Ziit vo Jesus gulte händ, weiss me nöd. De Aaklang a [[GEN.4.24]] beruet uf em gliiche griechische Zaalwort (FIND-MAT-3014).",
  []),
 ("BG-MAT-3016", U(18, 15, 20), "MAT.18.15-MAT.18.17", READERS, "probable", "Zurechtweisung vor Zeugen",
  "Das Gebot, den Nächsten zurechtzuweisen, statt ihn im Herzen zu hassen, steht in [[LEV.19.17]]; die Regel von zwei oder drei Zeugen stammt aus dem Rechtsverfahren ([[DEU.19.15]]; vgl. [[DEU.17.6]]). Die Gemeinschaft von Qumran kannte ein ähnliches Stufenverfahren: Man soll den anderen noch am selben Tag in Wahrheit und Demut zurechtweisen und eine Sache erst vor die Versammlung («die Vielen») bringen, nachdem man ihn vor Zeugen zurechtgewiesen hat. Auch dort konnte das Verfahren zum zeitweisen oder dauernden Ausschluss führen. Heiden und Zöllner galten in jüdischer Umgebung als Aussenstehende, mit denen man keine Tischgemeinschaft hielt (vgl. [[MAT.9.11]]; zu den Zöllnern BG-MRK-1005).",
  "Eine direkte Abhängigkeit zwischen Qumran und Matthäus ist nicht nachweisbar; die Ähnlichkeit zeigt eine verbreitete jüdische Praxis, die aus [[LEV.19.17]] und [[DEU.19.15]] entwickelt wurde.",
  ["MAT.18.15-MAT.18.17", "LEV.19.17", "DEU.19.15", "DEU.17.6", "MAT.9.11"],
  ["Qumran, Gemeinderegel (1QS) 5,24–6,1", "Qumran, Damaskusschrift (CD) 9,2–8"],
  [("grc", "ἐλέγχω", "zurechtweisen, überführen"), ("heb", "הוֹכֵחַ תּוֹכִיחַ", "du sollst gewiss zurechtweisen", "hôkēaḥ tôkîaḥ")],
  "Zrächtwiise vor Züüge",
  "S Gebot, de Nächscht zrächtzwiise, statt en im Härz z hasse, staat i [[LEV.19.17]]; d Regle vo zwei oder drüü Züüge chunnt us em Rächtsverfahre ([[DEU.19.15]]; vgl. [[DEU.17.6]]). D Gmeinschaft vo Qumran hät es ähnlichs Stuefeverfahre kännt: Me söll de ander no am gliiche Tag i Woret und Demuet zrächtwiise und e Sach erscht vor d Versammlig («di Vile») bringe, wänn me en vor Züüge zrächtgwise hät. Au dört hät s Verfahre zum ziitwiise oder bliibende Uusschluss chöne füere. Heide und Zöllner händ i jüdischer Umgäbig als Ussestehendi gulte, mit dene me kei Tischgmeinschaft ghalte hät (vgl. [[MAT.9.11]]; zu de Zöllner BG-MRK-1005).",
  "E diräkti Abhängigkeit zwüsche Qumran und em Matthäus cha me nöd nachwiise; d Ähnlichkeit zeigt e verbreiteti jüdischi Praxis, wo us [[LEV.19.17]] und [[DEU.19.15]] entwicklet worde isch.",
  ["zrächtwiise, überfüere", "du söllsch gwüss zrächtwiise"]),
 ("BG-MAT-3017", U(18, 21, 35), "MAT.18.24", READERS, "probable", "Talente, Denare und Schuldknechtschaft",
  "Ein Talent war eine Gewichts- und Rechnungseinheit von 6000 Drachmen bzw. Denaren; ein Denar war der Tageslohn eines Arbeiters ([[MAT.20.2]]). Zehntausend Talente sind also rund sechzig Millionen Denare, hundert Denare etwa der Lohn von hundert Arbeitstagen. Wie gross die erste Summe ist, zeigt ein Vergleich: Nach Josephus brachten die Gebiete, die die Söhne des Herodes erbten, zusammen jährlich einige hundert Talente an Abgaben. Zehntausend (μύριοι) war zugleich die höchste griechische Zahlbezeichnung. Dass ein Schuldner mit Frau und Kindern verkauft werden konnte, kennt auch die Bibel ([[2KI.4.1]]; vgl. [[LEV.25.39-LEV.25.42]], wonach Israeliten nicht wie Sklaven behandelt werden sollen); Gefängnis bis zur Bezahlung ([[MAT.18.30]]; vgl. [[MAT.5.25-MAT.5.26]]) und Folterknechte ([[MAT.18.34]]) passen eher zum Bild eines hellenistischen oder römischen Königshofes.",
  "Der Wert eines Talents schwankte nach Ort und Zeit; die Umrechnung gibt nur eine Grössenordnung. Ob Schuldhaft im jüdischen Recht der Zeit üblich war, ist umstritten.",
  ["MAT.18.23-MAT.18.35", "MAT.20.2", "2KI.4.1", "LEV.25.39-LEV.25.42", "MAT.5.25-MAT.5.26"],
  ["Josephus, Jüdische Altertümer 17,318–320"],
  [("grc", "τάλαντον", "Talent (Gewichts- und Geldeinheit)"), ("grc", "δηνάριον", "Denar"), ("grc", "μύριοι", "zehntausend")],
  "Talänt, Denar und Schuldchnächtschaft",
  "Es Talänt isch e Gwichts- und Rächnigseiheit vo 6000 Drachme bzw. Denar gsii; en Denar isch de Tagloon vo me Arbeiter gsii ([[MAT.20.2]]). Zäätuusig Talänt sind also öppe sächzg Millione Denar, hundert Denar öppe de Loon vo hundert Arbetstäg. Wie gross di erscht Summe isch, zeigt en Vergliich: Nach em Josephus händ d Gebiet, wo d Söön vom Herodes gerbt händ, zäme jedes Jaar es paar hundert Talänt a Abgaabe iibrocht. Zäätuusig (μύριοι) isch zuglich di höchscht griechisch Zaalbezeichnig gsii. Dass me en Schuldner mit Frau und Chind hät chöne verchaufe, kännt au d Bible ([[2KI.4.1]]; vgl. [[LEV.25.39-LEV.25.42]], wo Israelite nöd wie Sklave söled behandlet wärde); Gfängnis bis zur Zalig ([[MAT.18.30]]; vgl. [[MAT.5.25-MAT.5.26]]) und Folterchnächt ([[MAT.18.34]]) passed eher zum Bild vo me hellenistische oder römische Chünigshof.",
  "De Wärt vo me Talänt hät nach Ort und Ziit gschwanket; d Umrächnig git nu e Gröössenornig. Öb Schuldhaft im jüdische Rächt vo dere Ziit üblich gsii isch, isch umstritte.",
  ["Talänt (Gwichts- und Gäldeiheit)", "Denar", "zäätuusig"]),
 ("BG-MAT-3018", U(19, 23, 30), "MAT.19.24", READERS, "probable", "Kamel und Nadelöhr",
  "Das Bild vom Kamel, das durch ein Nadelöhr geht ([[MAT.19.24]]), stellt das grösste Lasttier des Landes dem kleinsten Loch gegenüber; es ist eine bewusste Übertreibung für das Unmögliche (vgl. [[MAT.23.24]]). Der Babylonische Talmud gebraucht ein ähnliches Bild vom Elefanten, der durch ein Nadelöhr geht, für etwas Undenkbares. Die oft erzählte Deutung auf ein enges Stadttor namens «Nadelöhr» ist erst viel später belegt; auch die Lesart κάμιλος «Seil» statt κάμηλος «Kamel» in einigen späten Handschriften mildert das Bild nachträglich. Die Jünger verstehen den Satz als Unmöglichkeit («Wer kann dann gerettet werden?»), und Jesus bestätigt das: Bei Menschen ist es unmöglich, bei Gott aber ist alles möglich ([[MAT.19.25-MAT.19.26]]).",
  "Woher die Deutung auf ein Tor stammt, ist nicht sicher geklärt; ein Stadttor dieses Namens aus der Zeit Jesu ist nicht bekannt.",
  ["MAT.19.23-MAT.19.26", "MAT.23.24", "MRK.10.25", "LUK.18.25"],
  ["Babylonischer Talmud, Berachot 55b; Baba Mezia 38b"],
  [("grc", "κάμηλος", "Kamel"), ("grc", "κάμιλος", "Seil, Tau (späte Lesart)"), ("grc", "τρύπημα ῥαφίδος", "Nadelöhr")],
  "Kamel und Nadelööhr",
  "S Bild vom Kamel, wo dur es Nadelööhr gaat ([[MAT.19.24]]), stellt s gröscht Lasttier vom Land em chliinschte Loch gägenüber; es isch e bewussti Übertriibig für s Unmöglich (vgl. [[MAT.23.24]]). De Babylonisch Talmud bruucht es ähnlichs Bild vom Elefant, wo dur es Nadelööhr gaat, für öppis Undänkbars. D Düütig uf es ängs Stadttor mit em Name «Nadelööhr», wo oft verzellt wird, isch erscht vil spööter belegt; au d Läsart κάμιλος «Seil» statt κάμηλος «Kamel» i es paar spoote Handschrifte milderet s Bild nachträglich. D Jünger verstönd de Satz als Unmöglichkeit («Wär cha dänn grettet wärde?»), und de Jesus bestätiget das: Bi Mänsche isch es unmöglich, bi Gott aber isch alles möglich ([[MAT.19.25-MAT.19.26]]).",
  "Wohär d Düütig uf es Tor stammt, isch nöd sicher klärt; es Stadttor mit dem Name us de Ziit vo Jesus isch nöd bekannt.",
  ["Kamel", "Seil, Tau (spooti Läsart)", "Nadelööhr"]),
 ("BG-MAT-3019", U(19, 1, 12), "MAT.19.3", READERS, "probable", "Scheidung im Judentum der Zeit",
  "Nach [[DEU.24.1-DEU.24.4]] kann ein Mann seiner Frau einen Scheidebrief geben, wenn er an ihr «etwas Schändliches» (ʿerwat dābār) findet. Was das heisst, war umstritten. Die Mischna überliefert drei Meinungen: Die Schule Schammais liess als Grund nur Unzucht gelten, die Schule Hillels auch, wenn die Frau ihm das Essen verdorben hatte, Rabbi Akiba sogar, wenn er eine schönere fand. Josephus gibt das Gesetz so wieder, ein Mann dürfe sich «aus welchem Grund auch immer» scheiden lassen, und berichtet von seiner eigenen Scheidung. Die Frage «aus jedem Grund» ([[MAT.19.3]]) nimmt diese Debatte auf. Die Damaskusschrift aus Qumran begründet mit «männlich und weiblich schuf er sie» ([[GEN.1.27]]), dass ein Mann nicht zu Lebzeiten zwei Frauen nehmen soll. Nach jüdischem Recht sprach der Mann die Scheidung aus.",
  "Die Mischna ist um 200 n. Chr. aufgeschrieben; wie scharf die Schulen zur Zeit Jesu getrennt waren, ist nicht sicher. Ob sich die Qumranstelle nur gegen Vielehe oder auch gegen Wiederheirat nach einer Scheidung richtet, ist umstritten. Ob Frauen in Einzelfällen selbst die Scheidung aussprechen konnten, wird mit wenigen Zeugnissen diskutiert.",
  ["MAT.19.3-MAT.19.9", "DEU.24.1-DEU.24.4", "GEN.1.27", "MAT.5.31-MAT.5.32"],
  ["Mischna, Gittin 9,10", "Josephus, Jüdische Altertümer 4,253", "Josephus, Leben (Vita) 426", "Qumran, Damaskusschrift (CD) 4,20–5,2"],
  [("heb", "עֶרְוַת דָּבָר", "etwas Schändliches, Anstössiges", "ʿerwat dābār"), ("grc", "ἀποστάσιον", "Scheidebrief"), ("grc", "αἰτία", "Grund, Ursache")],
  "Scheidig im Judetum vo dere Ziit",
  "Nach [[DEU.24.1-DEU.24.4]] cha en Maa sinere Frau en Scheidigsbrief gää, wänn er a ire «öppis Schandbars» (ʿerwat dābār) findt. Was das heisst, isch umstritte gsii. D Mischna überliferet drüü Meinige: D Schuel vom Schammai hät als Grund nu Unzucht la gälte, d Schuel vom Hillel au, wänn d Frau em s Ässe verdorbe hät, de Rabbi Akiba sogar, wänn er e Schöneri gfunde hät. De Josephus git s Gsetz so wider, en Maa dörf sich «us wellem Grund au immer» scheide loo, und brichtet vo sinere eigete Scheidig. D Frag «us jedem Grund» ([[MAT.19.3]]) nimmt die Debatte uf. D Damaskusschrift us Qumran begründet mit «männlich und wiiblich hät er si gschaffe» ([[GEN.1.27]]), dass en Maa nöd z Läbziite zwei Fraue söll nää. Nach jüdischem Rächt hät de Maa d Scheidig uusgsproche.",
  "D Mischna isch um 200 n. Chr. ufgschribe; wie schaarf d Schuele zur Ziit vo Jesus trännt gsii sind, isch nöd sicher. Öb sich d Qumranstell nu gäge d Vilee oder au gäge s Wiederhürate nach ere Scheidig richtet, isch umstritte. Öb Fraue im Einzelfall d Scheidig sälber händ chöne uusspräche, wird mit wenige Zügnis diskutiert.",
  ["öppis Schandbars, Aastössigs", "Scheidigsbrief", "Grund, Ursach"]),
 ("BG-MAT-3020", U(19, 1, 12), "MAT.19.12", READERS, "probable", "Eunuchen",
  "Eunuchen waren entmannte Männer, die vor allem an Königshöfen als Kämmerer, Wächter oder Beamte dienten (vgl. [[ACT.8.27]]); daneben kannte man Männer, die von Geburt an zeugungsunfähig waren. Nach [[DEU.23.1]] durfte ein Entmannter nicht in die Versammlung des Herrn kommen; [[ISA.56.3-ISA.56.5]] verheisst dagegen den Eunuchen, die Gottes Bund halten, einen Namen im Haus Gottes. Josephus verlangt, Eunuchen zu meiden, und verurteilt die Kastration. Wer davon sprach, dass sich Menschen «um des Reiches der Himmel willen» selbst zu Eunuchen machen ([[MAT.19.12]]), gebrauchte in einer Umgebung, die Ehe und Nachkommen hoch schätzte und Kastration verachtete, ein provozierendes Bild.",
  "Ob Jesus mit dem Wort auf Vorwürfe gegen seine eigene Ehelosigkeit antwortete, wird vermutet, ist aber nicht belegt.",
  ["MAT.19.10-MAT.19.12", "DEU.23.1", "ISA.56.3-ISA.56.5", "ACT.8.27"], ["Josephus, Jüdische Altertümer 4,290–291"],
  [("grc", "εὐνοῦχος", "Eunuch, Entmannter; Kämmerer"), ("heb", "סָרִיס", "Eunuch; Hofbeamter", "sārîs")],
  "Eunuche",
  "Eunuche sind entmannti Manne gsii, wo vor allem a Chünigshöf als Kämmerer, Wächter oder Beamti dienet händ (vgl. [[ACT.8.27]]); näbedra hät me Manne kännt, wo vo Geburt aa nöd händ chöne Chind züüge. Nach [[DEU.23.1]] hät en Entmannte nöd i d Versammlig vom Herr dörfe choo; [[ISA.56.3-ISA.56.5]] verheisst dergäge de Eunuche, wo de Bund vo Gott halted, en Name im Huus vo Gott. De Josephus verlangt, dass me Eunuche meidet, und verurteilt d Kastration. Wär devo gredt hät, dass sich Mänsche «wäge em Riich vo de Himel» sälber zu Eunuche mached ([[MAT.19.12]]), hät i ere Umgäbig, wo Ee und Nachkomme hööch gschätzt und Kastration verachtet hät, es provozierends Bild bruucht.",
  "Öb de Jesus mit dem Wort uf Vorwürf gäge sini eigeti Eelosigkeit antwortet hät, wird vermuetet, isch aber nöd belegt.",
  ["Eunuch, Entmannte; Kämmerer", "Eunuch; Hofbeamte"]),
 ("BG-MAT-3021", U(19, 23, 30), "MAT.19.28", READERS, "probable", "Zwölf Throne und zwölf Stämme",
  "Zur Zeit Jesu bestanden die zwölf Stämme Israels nicht mehr als Ganzes; seit dem Untergang des Nordreichs (722 v. Chr.) lebten die meisten verstreut oder galten als verloren. Propheten und spätere Schriften erwarteten, dass Gott die Stämme am Ende wieder sammelt ([[EZK.37.15-EZK.37.22]]; [[EZK.47.13]]; [[SIR.48.10]]); in den Psalmen Salomos (17) soll der Sohn Davids das Volk sammeln und die Stämme richten. Die Kriegsrolle aus Qumran nennt in ihrer Ordnung für die Endzeit auch die Häupter der Stämme. Das Bild von Thronen zum Gericht stammt aus [[DAN.7.9-DAN.7.10]]; zum Thron des Menschensohns vgl. [[DAN.7.13-DAN.7.14]] und [[MAT.25.31]]. Die Zwölfzahl der Jünger ([[MAT.10.1-MAT.10.4]]) knüpft an diese Hoffnung an.",
  "Ob «richten» Gericht oder Herrschaft meint, ist offen (siehe Übersetzungsentscheidung zu [[MAT.19.28]]). Die Psalmen Salomos werden meist ins 1. Jahrhundert v. Chr. datiert; ganz sicher ist das nicht. Die Stelle der Kriegsrolle (1QM 2,1–3) liess sich nicht an einer frei zugänglichen Textausgabe nachschlagen.",
  ["MAT.19.27-MAT.19.29", "EZK.37.15-EZK.37.22", "EZK.47.13", "DAN.7.9-DAN.7.14", "MAT.10.1-MAT.10.4"],
  ["Psalmen Salomos 17", "Qumran, Kriegsrolle (1QM) 2,1–3"],
  [("grc", "παλιγγενεσία", "Neuschöpfung, Wiedergeburt (der Welt)"), ("grc", "θρόνος", "Thron")],
  "Zwölf Throon und zwölf Stämm",
  "Zur Ziit vo Jesus händ di zwölf Stämm vo Israel nüme als Ganzes bestande; sit em Undergang vom Nordriich (722 v. Chr.) händ di meischte verstreut gläbt oder händ als verlore gulte. Prophete und spööteri Schrifte händ erwartet, dass Gott d Stämm am Änd wider sammlet ([[EZK.37.15-EZK.37.22]]; [[EZK.47.13]]; [[SIR.48.10]]); i de Psalme Salomos (17) söll de Sohn vom David s Volk sammle und d Stämm richte. D Kriegsrolle us Qumran nännt i irer Ornig für d Ändziit au d Häupter vo de Stämm. S Bild vo Throon zum Gricht chunnt us [[DAN.7.9-DAN.7.10]]; zum Throon vom Mänschesohn vgl. [[DAN.7.13-DAN.7.14]] und [[MAT.25.31]]. D Zwölfzahl vo de Jünger ([[MAT.10.1-MAT.10.4]]) knüpft a die Hoffnig aa.",
  "Öb «richte» Gricht oder Herrschaft meint, isch offe (lueg d Übersetzigsentscheidig zu [[MAT.19.28]]). D Psalme Salomos wärded meischt is 1. Jaarhundert v. Chr. datiert; ganz sicher isch das nöd. D Stell vo de Kriegsrolle (1QM 2,1–3) hät me nöd i ere frei zuegängliche Textuusgaab chöne nachläse.",
  ["Neuschöpfig, Widergeburt (vo de Wält)", "Throon"]),
 ("BG-MAT-3022", U(20, 1, 16), "MAT.20.1-MAT.20.8", GAL, "probable", "Tagelöhner, Stunden und Lohn",
  "Tagelöhner wurden morgens auf dem Markt angeworben und arbeiteten bis zum Abend. Die Stunden zählte man von Sonnenaufgang an: Die dritte Stunde lag etwa um 9 Uhr, die sechste am Mittag, die neunte um 15 Uhr, die elfte eine Stunde vor Sonnenuntergang. Die Tora verlangt, dem Tagelöhner seinen Lohn noch am selben Tag zu geben ([[LEV.19.13]]; [[DEU.24.14-DEU.24.15]]); das tut der Hausherr ([[MAT.20.8]]). Ein Denar am Tag reichte knapp zum Unterhalt einer Familie. Wer bis zur elften Stunde keine Arbeit fand, verdiente an diesem Tag nichts. Bei der Weinlese im Spätsommer drängte die Zeit, was das wiederholte Anwerben erklären könnte.",
  "Wie viel ein Denar kaufte, schwankte nach Zeit und Ort; «knapp für eine Familie» ist eine verbreitete Schätzung. Dass es um die Weinlese geht, sagt der Text nicht.",
  ["MAT.20.1-MAT.20.16", "LEV.19.13", "DEU.24.14-DEU.24.15"], [],
  [("grc", "ἐργάτης", "Arbeiter"), ("grc", "δηνάριον", "Denar"), ("grc", "οἰκοδεσπότης", "Hausherr")],
  "Taglööner, Stunde und Loon",
  "Taglööner sind am Morge uf em Märt aagstellt worde und händ bis am Aabig gschaffet. D Stunde hät me vom Sunneufgang aa zellt: Di dritt Stund isch öppe um 9i gsii, di sächst am Mittag, di nüünt um 15 Uhr, di elft e Stund vor em Sunneundergang. D Tora verlangt, dass me em Taglööner sin Loon no am gliiche Tag git ([[LEV.19.13]]; [[DEU.24.14-DEU.24.15]]); das macht de Huusherr ([[MAT.20.8]]). En Denar am Tag hät knapp glanget, zum e Familie z ernähre. Wär bis zur elfte Stund kei Arbet gfunde hät, hät a dem Tag nüüt verdient. Bi de Wümmet im Spootsummer hät d Ziit drängt, das chönt s wiederholt Aastelle erkläre.",
  "Wie vil me mit eme Denar hät chöne chaufe, hät nach Ziit und Ort gschwanket; «knapp für e Familie» isch e verbreiteti Schätzig. Dass es um d Wümmet gaat, seit de Text nöd.",
  ["Arbeiter", "Denar", "Huusherr"]),
 ("BG-MAT-3023", U(20, 20, 28), "MAT.20.22", READERS, "probable", "Der Becher und die Plätze zur Rechten und zur Linken",
  "Der Becher ist in der Bibel ein Bild für das Geschick, das Gott einem Menschen zuteilt: im Guten der «Becher des Heils» ([[PSA.116.13]]), häufiger der Becher des Zorns, den Völker oder Jerusalem trinken müssen ([[ISA.51.17]]; [[ISA.51.22]]; [[JER.25.15]]; [[PSA.75.8]]). In Getsemani betet Jesus, dieser Becher möge an ihm vorübergehen ([[MAT.26.39]]). Die Plätze zur Rechten und zur Linken eines Königs waren Ehrenplätze der Mächtigsten (vgl. [[1KI.2.19]]; [[PSA.110.1]]). Bei Matthäus werden später zwei Räuber mit Jesus gekreuzigt, «einer zur Rechten und einer zur Linken» ([[MAT.27.38]]).",
  "Ob Matthäus mit [[MAT.20.21]] bewusst auf [[MAT.27.38]] vorausweist, ist Deutung.",
  ["MAT.20.20-MAT.20.23", "PSA.116.13", "ISA.51.17", "JER.25.15", "MAT.26.39", "MAT.27.38"], [],
  [("grc", "ποτήριον", "Becher, Kelch")],
  "De Bächer und d Plätz zur Rächte und zur Linke",
  "De Bächer isch i de Bible es Bild für s Gschick, wo Gott eme Mänsch zueteilt: im Guete de «Bächer vom Heil» ([[PSA.116.13]]), hüüfiger de Bächer vom Zorn, wo Völker oder Jerusalem müend trinke ([[ISA.51.17]]; [[ISA.51.22]]; [[JER.25.15]]; [[PSA.75.8]]). Z Getsemani bättet de Jesus, de Bächer söll a ihm verbiigaa ([[MAT.26.39]]). D Plätz zur Rächte und zur Linke vo me König sind Ehreplätz vo de Mächtigschte gsii (vgl. [[1KI.2.19]]; [[PSA.110.1]]). Bim Matthäus wärded spööter zwei Röiber mit em Jesus chrüziget, «eine zur Rächte und eine zur Linke» ([[MAT.27.38]]).",
  "Öb de Matthäus mit [[MAT.20.21]] bewusst uf [[MAT.27.38]] vorewiist, isch Düütig.",
  ["Bächer, Chelch"]),
 ("BG-MAT-3024", U(20, 29, 34), "MAT.20.30", READERS, "possible", "«Sohn Davids» als Ruf um Heilung",
  "«Sohn Davids» ist ein Titel des erwarteten Messias aus dem Haus David (vgl. [[2SA.7.12-2SA.7.16]]; [[MAT.1.1]]); in den Psalmen Salomos (17) soll Gott ihnen «ihren König, den Sohn Davids» erstehen lassen. Auffällig ist, dass der Titel bei Matthäus meist von Hilfesuchenden kommt, die um Heilung bitten ([[MAT.9.27]]; [[MAT.15.22]]; [[MAT.20.30-MAT.20.31]]; vgl. [[MAT.12.22-MAT.12.23]]). Manche verbinden das mit dem Ruf Salomos, des Sohnes Davids: Josephus berichtet, Gott habe Salomo die Kunst gegen Dämonen gelehrt, und erzählt von einem Juden Eleasar, der mit Beschwörungen Salomos Dämonen austrieb. Der Messias als Heiler und der Sohn Davids als Hirte der Verlorenen ([[EZK.34.23]]) können hier zusammenfliessen.",
  "Ob Matthäus oder seine Leser beim Ruf «Sohn Davids» an Salomo als Heiler dachten, ist eine umstrittene These; das Testament Salomos, das diese Überlieferung ausbaut, ist jünger.",
  ["MAT.20.29-MAT.20.34", "MAT.9.27", "MAT.15.22", "MAT.12.22-MAT.12.23", "2SA.7.12-2SA.7.16", "EZK.34.23"],
  ["Psalmen Salomos 17,21", "Josephus, Jüdische Altertümer 8,45–49"],
  [("grc", "υἱὸς Δαυίδ", "Sohn Davids")],
  "«Sohn vom David» als Ruef um Heilig",
  "«Sohn vom David» isch en Titel vom erwartete Messias us em Huus David (vgl. [[2SA.7.12-2SA.7.16]]; [[MAT.1.1]]); i de Psalme Salomos (17) söll Gott ine «ire König, de Sohn vom David» la uufstaa. Es fallt uf, dass de Titel bim Matthäus meischt vo Mänsche chunnt, wo Hilf sueched und um Heilig bitted ([[MAT.9.27]]; [[MAT.15.22]]; [[MAT.20.30-MAT.20.31]]; vgl. [[MAT.12.22-MAT.12.23]]). Mängi verbinded das mit em Ruef vom Salomo, em Sohn vom David: De Josephus brichtet, Gott heg em Salomo d Kunscht gäge Dämone glehrt, und verzellt vo me Jud Eleasar, wo mit Beschwörige vom Salomo Dämone usgtribe heg. De Messias als Heiler und de Sohn vom David als Hirt vo de Verlorne ([[EZK.34.23]]) chönd da zämefliesse.",
  "Öb de Matthäus oder sini Läser bim Ruef «Sohn vom David» a de Salomo als Heiler dänkt händ, isch e umstritteni These; s Teschtament vom Salomo, wo die Überliferig uusbaut, isch jünger.",
  ["Sohn vom David"]),
 ("BG-MAT-3025", U(21, 1, 11), "MAT.21.8-MAT.21.9", TEMPLE, "probable", "Hosanna, Mäntel und Zweige",
  "«Hosanna» ist die griechische Umschrift des hebräischen hôšîʿâ nnāʾ «hilf doch!» aus [[PSA.118.25]]. Psalm 118 gehört zum Hallel ([[PSA.113.1-PSA.118.29]]), das an den grossen Festen gesungen wurde. Nach der Mischna wurde am Laubhüttenfest beim Hosanna-Ruf aus Psalm 118 der Feststrauss geschwungen, und man zog mit dem Ruf «Ach Herr, hilf doch!» um den Altar. So wurde der Ruf auch zum Jubel- und Huldigungsruf. Mäntel auf dem Weg auszubreiten war eine Huldigung für einen neuen König ([[2KI.9.13]]); mit Palmzweigen und Gesang zog Simon der Makkabäer in die Burg von Jerusalem ein ([[1MA.13.51]]), und bei der Tempelweihe trug man Zweige ([[2MA.10.7]]). Der Zuruf «Gesegnet sei, der kommt im Namen des Herrn» ist [[PSA.118.26]].",
  "Wie weit die Festbräuche der Mischna schon im 1. Jahrhundert so geübt wurden, ist nicht in allen Einzelheiten sicher.",
  ["MAT.21.8-MAT.21.9", "MAT.21.15", "PSA.118.25-PSA.118.26", "2KI.9.13", "1MA.13.51", "2MA.10.7"],
  ["Mischna, Sukka 3,9; 4,5"],
  [("grc", "ὡσαννά", "Hosanna (Umschrift)"), ("heb", "הוֹשִׁיעָה נָּא", "hilf doch!", "hôšîʿâ nnāʾ")],
  "Hosanna, Mäntel und Zweig",
  "«Hosanna» isch di griechisch Umschrift vom hebräische hôšîʿâ nnāʾ «hilf doch!» us [[PSA.118.25]]. De Psalm 118 ghört zum Hallel ([[PSA.113.1-PSA.118.29]]), wo a de grosse Fescht gsunge worde isch. Nach de Mischna isch am Laubhüttefescht bim Hosanna-Ruef us em Psalm 118 de Feschtstruuss gschwunge worde, und me isch mit em Ruef «Ach Herr, hilf doch!» um de Altar zoge. So isch de Ruef au zum Jubel- und Huldigungsruef worde. Mäntel uf em Wäg uusbreite isch e Huldigung für en nöie König gsii ([[2KI.9.13]]); mit Palmzweig und Gsang isch de Simon, de Makkabäer, i d Burg vo Jerusalem iizoge ([[1MA.13.51]]), und bi de Tämpelwiiig hät me Zweig treit ([[2MA.10.7]]). De Zueruef «Gsägnet sig dä, wo chunnt im Name vom Herr» isch [[PSA.118.26]].",
  "Wie wiit d Feschtbrüüch vo de Mischna scho im 1. Jaarhundert eso gmacht worde sind, isch nöd i allne Einzelheite sicher.",
  ["Hosanna (Umschrift)", "hilf doch!"]),
 ("BG-MAT-3026", U(21, 12, 17), "MAT.21.14", TEMPLE, "probable", "Blinde und Lahme im Tempel",
  "Nach [[2SA.5.8]] entstand das Sprichwort: «Ein Blinder und ein Lahmer soll nicht ins Haus kommen.» Priester mit einem Gebrechen, etwa Blinde oder Lahme, durften keine Opfer darbringen ([[LEV.21.17-LEV.21.23]]). Die Mischna befreit Lahme und Blinde von der Pflicht, an den Festen im Tempel zu erscheinen. In Schriften aus Qumran werden Blinde von der Tempelstadt und Menschen mit Gebrechen von der Versammlung der Gemeinschaft ferngehalten. Dass Blinde und Lahme gerade im Tempel zu Jesus kommen und geheilt werden ([[MAT.21.14]]), steht vor diesem Hintergrund; zu Händlern und Geldwechslern im Tempel siehe BG-MRK-2003.",
  "Ob Blinde und Lahme zur Zeit Jesu tatsächlich vom Tempel ferngehalten wurden, ist nicht sicher; die Regeln aus Qumran galten für die eigene Gemeinschaft und deren Ideal, nicht für den Tempelbetrieb in Jerusalem.",
  ["MAT.21.12-MAT.21.15", "2SA.5.8", "LEV.21.17-LEV.21.23"],
  ["Mischna, Chagiga 1,1", "Qumran, Tempelrolle (11QT) 45,12–14", "Qumran, Gemeinschaftsregel (1QSa) 2,3–9"],
  [("grc", "τυφλός", "blind"), ("grc", "χωλός", "lahm")],
  "Blindi und Lahmi im Tämpel",
  "Nach [[2SA.5.8]] isch s Sprichwort entstande: «En Blinde und en Lahme söll nöd is Huus choo.» Prieschter mit eme Gebräche, öppe Blindi oder Lahmi, händ kei Opfer dörfe darbringe ([[LEV.21.17-LEV.21.23]]). D Mischna befreit Lahmi und Blindi vo de Pflicht, a de Fescht im Tämpel z erschiine. I Schrifte us Qumran wärded Blindi vo de Tämpelstadt und Mänsche mit Gebräche vo de Versammlig vo de Gmeinschaft fernghalte. Dass Blindi und Lahmi grad im Tämpel zum Jesus chömed und gheilt wärded ([[MAT.21.14]]), staat vor dem Hindergrund; zu Händler und Gäldwächsler im Tämpel lueg BG-MRK-2003.",
  "Öb Blindi und Lahmi zur Ziit vo Jesus würkli vom Tämpel fernghalte worde sind, isch nöd sicher; d Regle us Qumran händ für di eiget Gmeinschaft und ires Ideal gulte, nöd für de Tämpelbetrieb z Jerusalem.",
  ["blind", "lahm"]),
 ("BG-MAT-3027", U(21, 18, 22), "MAT.21.19", GAL, "probable", "Der Feigenbaum",
  "Feigenbäume treiben im Land Israel im Frühjahr Blätter; zugleich oder kurz zuvor setzen kleine, unreife Frühfeigen an, die Haupternte folgt im Spätsommer. Ein Baum mit Blättern, aber ohne jeden Fruchtansatz kann als unfruchtbar gelten. Die Propheten gebrauchen den Feigenbaum als Bild für Israel: Gott fand Israel wie Frühfeigen ([[HOS.9.10]]); er sucht Feigen und findet keine ([[JER.8.13]]; [[MIC.7.1]]). Matthäus lässt die Bemerkung des Markus über die Jahreszeit weg ([[MRK.11.13]]); er erzählt das Verdorren auf der Stelle als Zeichen und als Anlass für ein Wort über den Glauben.",
  "Wie weit Frühfeigen zur Passazeit vorhanden oder essbar waren, wird verschieden beurteilt; daraus lässt sich der Sinn der Erzählung nicht ableiten.",
  ["MAT.21.18-MAT.21.22", "HOS.9.10", "JER.8.13", "MIC.7.1", "MRK.11.13"], [],
  [("grc", "συκῆ", "Feigenbaum"), ("heb", "פַּגִּים", "unreife Frühfeigen", "paggîm")],
  "De Fiigebaum",
  "Fiigebäum triibed im Land Israel im Früelig Bletter; zur gliiche Ziit oder churz vorher setzed chlii, unriifi Früefiige aa, d Hauptärnt chunnt im Spootsummer. En Baum mit Bletter, aber ganz ohni Fruchtaasatz cha als unfruchtbar gälte. D Prophete bruuched de Fiigebaum als Bild für Israel: Gott hät Israel gfunde wie Früefiige ([[HOS.9.10]]); er suecht Fiige und findt kei ([[JER.8.13]]; [[MIC.7.1]]). De Matthäus laat d Bemerkig vom Markus über d Jaresziit wäg ([[MRK.11.13]]); er verzellt s Verdorre uf de Stell als Zeiche und als Aalass für es Wort über de Glaube.",
  "Wie wiit Früefiige zur Passaziit dagsii oder ässbar gsii sind, wird verschide beurteilt; drus cha me de Sinn vo de Gschicht nöd ableite.",
  ["Fiigebaum", "unriifi Früefiige"]),
 ("BG-MAT-3028", U(21, 33, 46), "MAT.21.33", GAL, "probable", "Weinberg, Pacht und der verworfene Stein",
  "Die Beschreibung in [[MAT.21.33]] – Zaun, Kelter, Turm – nimmt das Weinberglied aus [[ISA.5.1-ISA.5.7]] auf, in dem der Weinberg das Haus Israel ist. Grundbesitzer, die anderswo lebten und ihr Land an Pächter vergaben, gab es in Galiläa und Judäa seit hellenistischer Zeit; Papyri aus dem Archiv eines Verwalters namens Zenon (3. Jahrhundert v. Chr.) berichten von einem Weinberg in Galiläa (Baitanata); ein weiterer Brief aus dem Archiv, der meist auf dasselbe Gut bezogen wird, erzählt von Klagen der Pächter und Streit um die abzuliefernde Menge. Die Pacht wurde oft mit einem Anteil der Ernte bezahlt, abzuholen zur Zeit der Früchte. Eine Fassung des Gleichnisses ohne Schriftzitat und ohne erkennbaren Bezug auf Israel steht im Thomasevangelium (Logion 65); das Wort vom verworfenen Stein folgt dort als eigener Spruch (Logion 66). Der «Stein, den die Bauleute verworfen haben» stammt aus [[PSA.118.22-PSA.118.23]]; der Psalm wird auch in [[ACT.4.11]] und [[1PE.2.7]] auf Jesus gedeutet.",
  "Wie verbreitet abwesende Grundherren zur Zeit Jesu waren, ist in der Forschung umstritten. Ob die Fassung im Thomasevangelium älter ist als die der Evangelien, ist offen.",
  ["MAT.21.33-MAT.21.43", "ISA.5.1-ISA.5.7", "PSA.118.22-PSA.118.23", "ACT.4.11", "1PE.2.7"],
  ["Zenon-Papyri (3. Jahrhundert v. Chr.): P.Lond. 7,1948; PSI 6,554", "Thomasevangelium, Logion 65–66"],
  [("grc", "γεωργός", "Bauer, Pächter, Weinbauer"), ("heb", "כֶּרֶם", "Weinberg", "kerem")],
  "Wiibärg, Pacht und de verworfe Stei",
  "D Bschriibig i [[MAT.21.33]] – Haag, Trotte, Turm – nimmt s Wiibärglied us [[ISA.5.1-ISA.5.7]] uf, wo de Wiibärg s Huus Israel isch. Grundbsitzer, wo anderswo gläbt und ires Land a Pächter ggää händ, hät s in Galiläa und Judäa sit de hellenistische Ziit ggää; Papyri us em Archiv vo me Verwalter mit em Name Zenon (3. Jaarhundert v. Chr.) brichted vo me Wiibärg in Galiläa (Baitanata); en wiitere Brief us em Archiv, wo me meischt uf s gliich Guet bezieht, verzellt vo Chlage vo de Pächter und vo Striit um d Mängi, wo si händ müese abliifere. D Pacht isch oft mit eme Teil vo de Ärnt zalt worde, abzhole zur Ziit vo de Frücht. E Fassig vom Gliichnis ohni Schriftzitat und ohni erchännbare Bezug uf Israel staat im Thomasevangelium (Logion 65); s Wort vom verworfne Stei chunnt dört als eigete Spruch (Logion 66). De «Stei, wo d Buulüüt verworfe händ» chunnt us [[PSA.118.22-PSA.118.23]]; de Psalm wird au i [[ACT.4.11]] und [[1PE.2.7]] uf de Jesus tüütet.",
  "Wie verbreitet Grundherre, wo nöd vor Ort gläbt händ, zur Ziit vo Jesus gsii sind, isch i de Forschig umstritte. Öb d Fassig im Thomasevangelium elter isch als die vo de Evangelie, isch offe.",
  ["Buur, Pächter, Wiibuur", "Wiibärg"]),
]

