# Kapitel-Zusammenfassungen (de, Mundart)
SUMMARIES = [
 ("SUM-CH-MAT-015", "Pharisäer und Schriftgelehrte aus Jerusalem werfen Jesus vor, seine Jünger übertreten die Überlieferung der Ältesten; Jesus hält ihnen vor, dass sie mit ihrer Überlieferung Gottes Gebot ausser Kraft setzen, und lehrt: Unrein macht, was aus dem Herzen kommt, nicht das Essen mit ungewaschenen Händen. In der Gegend von Tyros und Sidon heilt er die Tochter einer kanaanäischen Frau, weil ihr Glaube gross ist. Am See von Galiläa heilt er auf dem Berg viele Kranke und speist viertausend Männer, ohne Frauen und Kinder, mit sieben Broten und ein paar Fischen.",
  "Pharisäer und Schriftgelehrti vo Jerusalem werfed em Jesus vor, sini Jünger verstoossed gäge d Überliferig vo de Ältischte; de Jesus hebt ine vor, dass si mit irer Überliferig s Gebot vo Gott usser Chraft setzed, und lehrt: Unrein macht, was us em Härz chunnt, nöd s Ässe mit ungwäschne Händ. I de Gäged vo Tyros und Sidon heilt er d Tochter vo ere kanaanäische Frau, wil ire Glaube gross isch. Am See vo Galiläa heilt er uf em Bärg vil Chranki und spiist viertuusig Manne, ohni Fraue und Chind, mit sibe Broot und es paar Fischli."),
 ("SUM-CH-MAT-016", "Pharisäer und Sadduzäer fordern ein Zeichen; Jesus verweist auf das Zeichen des Jona und warnt die Jünger vor ihrem Sauerteig, ihrer Lehre. Bei Cäsarea Philippi bekennt Petrus: «Du bist der Christus, der Sohn des lebendigen Gottes!» Jesus preist ihn selig, sagt, auf diesen Felsen werde er seine Gemeinde bauen, verspricht ihm die Schlüssel des Reichs der Himmel und verbietet den Jüngern, zu sagen, dass er der Christus ist. Dann kündigt er zum ersten Mal an, dass er in Jerusalem leiden, getötet und am dritten Tag auferweckt werden muss, weist Petrus zurecht, ruft zur Nachfolge mit dem Kreuz und kündigt an, dass der Menschensohn in der Herrlichkeit seines Vaters kommen wird.",
  "Pharisäer und Sadduzäer fordered es Zeiche; de Jesus verwiist ufs Zeiche vom Jona und warnt d Jünger vor irem Suurteig, irer Lehr. Bi Cäsarea Philippi bekännt de Petrus: «Du bisch de Christus, de Sohn vom läbige Gott!» De Jesus priist en sälig, seit, uf dä Felse wärd er sini Gmeind buue, verspricht em d Schlüssel vom Riich vo de Himel und verbietet de Jünger, z säge, dass er de Christus isch. Dänn chündet er s erscht Mal aa, dass er z Jerusalem mues liide, umbracht und am dritte Tag uferweckt wärde, wiist de Petrus zrächt, rüeft zur Nachfolg mit em Chrüüz und chündet aa, dass de Mänschesohn i de Herrlichkeit vo sim Vatter wird choo."),
 ("SUM-CH-MAT-017", "Auf einem hohen Berg wird Jesus vor Petrus, Jakobus und Johannes verwandelt; Mose und Elija reden mit ihm, und eine Stimme aus der Wolke sagt: «Dieser ist mein Sohn … hört auf ihn!» Beim Abstieg sagt Jesus, Elija sei schon gekommen, und die Jünger verstehen, dass er von Johannes dem Täufer spricht. Jesus heilt einen mondsüchtigen Jungen, den die Jünger wegen ihres Kleinglaubens nicht heilen konnten, und kündigt erneut seinen Tod und seine Auferweckung an. In Kafarnaum trägt er Petrus auf, die Doppeldrachme für sie beide mit einem Stater zu bezahlen, den er im Maul eines Fisches finden werde.",
  "Uf eme hööche Bärg wird de Jesus vor em Petrus, em Jakobus und em Johannes verwandlet; de Mose und de Elija reded mit ihm, und e Stimm us de Wolche seit: «Das isch min Sohn … losed uf en!» Bim Abstiig seit de Jesus, de Elija sig scho choo, und d Jünger verstönd, dass er vom Johannes, em Täufer, redt. De Jesus heilt en mondsüchtige Bueb, wo d Jünger wäge irem Chliiglaube nöd händ chöne heile, und chündet nomal sin Tod und sini Uferweckig aa. Z Kafarnaum träit er em Petrus uf, d Doppeldrachme für si beid mit eme Stater z zale, won er im Muul vo me Fisch wärdi finde."),
 ("SUM-CH-MAT-018", "Auf die Frage, wer der Grösste im Reich der Himmel sei, stellt Jesus ein Kind in die Mitte: Wer sich klein macht wie dieses Kind, ist der Grösste. Er warnt davor, einen dieser Kleinen zu Fall zu bringen oder zu verachten, und erzählt vom Menschen, der das verirrte Schaf sucht. Er zeigt, wie man einen Bruder, der sündigt, zurechtweist, zuerst unter vier Augen, spricht den Jüngern die Vollmacht zu binden und zu lösen zu und verheisst seine Gegenwart, wo zwei oder drei in seinem Namen versammelt sind. Auf die Frage des Petrus sagt er, man solle siebenundsiebzigmal vergeben, und erzählt das Gleichnis vom Knecht, dem eine riesige Schuld erlassen wird, der aber seinem Mitknecht nicht vergibt.",
  "Uf d Frag, wär de Gröscht im Riich vo de Himel sig, stellt de Jesus es Chind i d Mitti: Wär sich chlii macht wie das Chind, isch de Gröscht. Er warnt devor, eine vo dene Chliine z Fall z bringe oder z verachte, und verzellt vom Mänsch, wo s verirrt Schaf suecht. Er zeigt, wie me en Brueder, wo sündiget, zur Red stellt, zerscht under vier Auge, spricht de Jünger d Vollmacht zue, z binde und z löse, und verheisst, dass er derbii isch, wo zwei oder drüü i sim Name versammlet sind. Uf d Frag vom Petrus seit er, me söll sibenesibezg Mal vergää, und verzellt s Gliichnis vom Chnächt, wo e riisigi Schuld erlaa überchunnt, aber sim Mitchnächt nöd vergit."),
 ("SUM-CH-MAT-019", "Jesus zieht von Galiläa in das Gebiet von Judäa jenseits des Jordan. Pharisäer fragen ihn, ob ein Mann seine Frau aus jedem Grund entlassen darf; Jesus verweist auf die Schöpfung: Was Gott zusammengefügt hat, soll der Mensch nicht trennen, und wer seine Frau entlässt, ausser wegen Unzucht, und eine andere heiratet, bricht die Ehe. Er spricht von Eunuchen um des Reiches der Himmel willen und legt Kindern die Hände auf. Einem jungen Mann sagt er, er solle seinen Besitz den Armen geben und ihm nachfolgen; der geht traurig weg. Jesus sagt, wie schwer ein Reicher in das Reich kommt, bei Gott aber sei alles möglich, und verheisst denen, die ihm nachgefolgt sind, reichen Lohn; viele Erste werden Letzte sein.",
  "De Jesus ziet vo Galiläa is Gebiet vo Judäa änet em Jordan. Pharisäer fröged en, öb en Maa sini Frau us jedem Grund dörf entlaa; de Jesus verwiist uf d Schöpfig: Was Gott zämegfüegt hät, söll de Mänsch nöd trenne, und wär sini Frau entlaat, usser wäge Unzucht, und en anderi hüratet, bricht d Ee. Er redt vo Eunuche wäge em Riich vo de Himel und leit Chind d Händ uf. Eme junge Maa seit er, er söll sin Bsitz de Arme gää und ihm nachefolge; dä gaat truurig devo. De Jesus seit, wie schwär en Riiche is Riich chunnt, bi Gott aber sig alles möglich, und verheisst dene, wo ihm nachegfolget sind, riiche Loon; vil Erschti wärded Letschti sii."),
 ("SUM-CH-MAT-020", "Jesus erzählt das Gleichnis vom Hausherrn, der allen Arbeitern im Weinberg denselben Lohn gibt, auch denen, die nur eine Stunde gearbeitet haben: So werden die Letzten Erste sein. Auf dem Weg nach Jerusalem kündigt er den Zwölf zum dritten Mal sein Leiden an: Er wird ausgeliefert, verspottet, ausgepeitscht und gekreuzigt und am dritten Tag auferweckt werden. Die Mutter der Söhne des Zebedäus bittet um die Ehrenplätze für ihre Söhne; Jesus lehrt, dass unter seinen Jüngern gross ist, wer dient, so wie der Menschensohn, der gekommen ist, um zu dienen und sein Leben als Lösegeld für viele zu geben. Bei Jericho heilt er zwei Blinde, die ihn als Sohn Davids anrufen; sie folgen ihm nach.",
  "De Jesus verzellt s Gliichnis vom Huusherr, wo allne Arbeiter im Wiibärg de gliich Loon git, au dene, wo nu e Stund gschaffet händ: So wärded di Letschte Erschti sii. Uf em Wäg uf Jerusalem chündet er de Zwölf s dritt Mal sis Liide aa: Er wird usgliferet, verspottet, uspeitscht und chrüziget und am dritte Tag uferweckt wärde. D Mueter vo de Söön vom Zebedäus bittet um d Ehreplätz für iri Söön; de Jesus lehrt, dass under sine Jünger gross isch, wär dient, eso wie de Mänschesohn, wo choo isch, zum diene und zum sis Läbe als Lösgäld für vili gää. Bi Jericho heilt er zwei Blindi, wo en als Sohn vom David aarüefed; si folged em nache."),
 ("SUM-CH-MAT-021", "Jesus lässt zwei Jünger eine Eselin und ein Fohlen holen und zieht in Jerusalem ein; so erfüllt sich ein Prophetenwort, und die Menschenmengen rufen: «Hosanna dem Sohn Davids!» Im Tempel treibt er Verkäufer und Käufer hinaus, heilt Blinde und Lahme und verteidigt die Kinder, die ihm zujubeln. Ein Feigenbaum ohne Frucht verdorrt auf sein Wort hin, und Jesus spricht über Glauben und Gebet. Den Hohepriestern und Ältesten, die nach seiner Vollmacht fragen, stellt er eine Gegenfrage nach der Taufe des Johannes, und als sie sagen, sie wüssten es nicht, sagt er ihnen nicht, in welcher Vollmacht er handelt. Er erzählt die Gleichnisse von den zwei Söhnen und von den Weinbauern, die den Sohn des Besitzers töten, und sagt, das Reich Gottes werde ihnen weggenommen. Die Hohepriester und Pharisäer wollen ihn festnehmen, fürchten aber die Menge.",
  "De Jesus laat zwei Jünger e Eselin und es Füli hole und ziet z Jerusalem ii; so erfüllt sich es Prophetewort, und d Lüüt rüefed: «Hosanna em Sohn vom David!» Im Tämpel jagt er Verchäufer und Chäufer use, heilt Blindi und Lahmi und nimmt d Chind in Schutz, wo ihm zuejubled. En Fiigebaum ohni Frucht verdorret uf sis Wort hii, und de Jesus redt über Glaube und Bätte. De Hoheprieschter und Ältischte, wo nach sinere Vollmacht fröged, stellt er e Gägefrag nach de Taufi vom Johannes, und wo si säged, si wüssed s nöd, seit er ine nöd, mit was für ere Vollmacht er handlet. Er verzellt d Gliichnis vo de zwei Söön und vo de Wiibuure, wo de Sohn vom Bsitzer umbringed, und seit, s Riich vo Gott wärd ine wäggnoo. D Hoheprieschter und d Pharisäer wänd en feschtnää, händ aber Angscht vor de Lüüt."),
]


def run():
    extra = sorted((p.stem for p in (D / "translations").rglob("TRANS-MAT-0*-WORKING.json")
                    if re.fullmatch(r"TRANS-MAT-0(1[5-9]|2[01])-\d{3}-\d{3}-(DE|GSW-ZH)-WORKING", p.stem)),
                   key=lambda x: ("-GSW-" in x, x))
    for sid in ("STUDY-MAT-0004",):
        p = D / "studies" / f"{sid}.json"
        if p.exists() and "Matthäus 15–21" not in json.loads(p.read_text(encoding="utf-8")).get("title", ""):
            raise SystemExit(f"{sid} existiert schon mit anderem Inhalt; nicht überschreiben")
    for sid, _, _ in SUMMARIES:
        p = D / "summaries" / f"{sid}.json"
        if p.exists() and "matthaeus_study_c" not in p.read_text(encoding="utf-8") \
                and _study.AUTH not in p.read_text(encoding="utf-8"):
            raise SystemExit(f"{sid} existiert schon aus einem anderen Werkzeug; nicht überschreiben")
    _study.write_study({"TAGS": TAGS, "CONTEXT": CONTEXT, "FINDINGS": FINDINGS, "INTERPRETATIONS": INTERPRETATIONS,
                        "PRINCIPLES": PRINCIPLES, "APPLICATIONS": APPLICATIONS, "QUESTIONS": QUESTIONS,
                        "RELATIONS": RELATIONS, "BACKGROUND": BACKGROUND, "SUMMARIES": SUMMARIES,
                        "STUDY": ("STUDY-MAT-0004", "Matthäus 15–21: Studieninhalte", CHAPTERS[15],
                                  extra + [s[0] for s in SUMMARIES],
                                  ["Mundart muttersprachlich prüfen",
                                   "Fachliche Prüfung der Deutungen und des Hintergrunds",
                                   "Sekundärangaben (Josephus-, Mischna-, Talmud-, Qumran- und Plutarch-Stellen; "
                                   "Elephantine-Beleg zu Kephas; Zenon-Papyri; Umrechnung der Talente) an Fachquellen nachprüfen",
                                   "Zählungen beruhen auf MACULA-Lemmata zum SBLGNT; andere Editionen können abweichen"]),
                        "SOURCE_CHECKS": SOURCE_CHECKS},
                       "Matthäus 15–21")


if __name__ == "__main__":
    run()
